ConvertCapacity storage convertCap = s.sys.convertCapacity[block.number];
if (convertCap.overallConvertCapacityUsed >= overallCappedDeltaB) {
    cumulativePenalty = overallAmountInDirectionOfPeg;
} else if (overallAmountInDirectionOfPeg > overallCappedDeltaB.sub(convertCap.overallConvertCapacityUsed)) {
    cumulativePenalty = overallAmountInDirectionOfPeg - overallCappedDeltaB.sub(convertCap.overallConvertCapacityUsed);
}

uint256 amountOut = IWell(wellDeltaB.well).swapFrom(
    C.bean(),
    sopToken,
    sopBeans,
    0,
    address(this),
    type(uint256).max
);
rewardSop(wellDeltaB.well, amountOut, address(sopToken));

if (s.sys.season.rainStart > lastUpdate) {
    s.accts[account].lastRain = s.sys.season.rainStart;
    s.accts[account].sop.rainRoots = s.accts[account].roots;
}
// ... rewardSop divides by s.sys.rain.roots (set = s.sys.silo.roots at rain start, before endTotalGermination)
